import { extractKeywords as extractBaseKeywords } from "@/lib/textKeywords";

// Extracted from the Guards of Atlantis II rulebook PDF (2nd Printing) via
// pdf-parse, baked in as a static constant rather than a Supabase table —
// unlike Discord history, the rulebook is fixed reference material that
// doesn't need re-syncing, so it lives here the same way lib/heroes.ts and
// lib/badges.ts do. Re-generate by re-running the same extraction if a new
// printing/errata comes out.

// The rulebook is ~24k tokens on its own — unlike hero cards or Discord
// history, it isn't filtered down to a relevant slice (it's raw PDF-page
// text, not data keyed by hero/topic, so there's no safe unit smaller than
// "the whole thing" to select without risking silently cutting the exact
// page that answers the question). Instead it's gated on/off: included
// whenever a question doesn't clearly need it costs nothing in quality but
// was previously burning ~10% of Gemini's free-tier per-minute token
// budget on every single request regardless of topic — the same fixed cost
// that, stacked with hero card/guide context on a multi-hero question,
// pushed a single request over the free-tier limit (see lib/discordContext.ts).
// Deliberately biased toward matching: a false positive just spends the
// ~24k tokens on a question that turned out not to need them, while a
// false negative risks the model wrongly saying "I don't have that rule"
// on a question the rulebook could have actually answered — same
// asymmetry as STRATEGY_INTENT_PATTERNS in lib/heroCardContext.ts. Only
// meant to gate the rulebook within a hero/strategy question (see its call
// site in app/api/chat/route.ts) — a question with no hero/strategy intent
// at all already gets the rulebook unconditionally, since that's the
// question type it serves most directly.
const RULES_INTENT_PATTERNS = [
  /\brules?\b/, /\brulebook\b/, /\brulings?\b/, /\blegal(ly)?\b/,
  /\ballow(ed|s)?\b/, /\bcan i\b/, /\bcan you\b/, /\bam i\b/,
  /\bis (it|this|that) (legal|allowed|possible|valid)\b/,
  /\bline of sight\b/, /\bminion battle\b/, /\bthrone\b/,
  /\btiebreaker\b/, /\binitiative order\b/, /\bstack(s|ing|ed)?\b/,
  /\bsimultaneous(ly)?\b/, /\border of operations\b/,
  /\bwhat happens (if|when)\b/, /\bdoes .*\bwork\b/, /\bcounts as\b/,
  /\bofficial rule\b/, /\bhouse rule\b/,
];

export function wantsRulebookContext(question: string): boolean {
  const lower = question.toLowerCase();
  return RULES_INTENT_PATTERNS.some((re) => re.test(lower));
}

